"""Deterministic dependency-bound S08 eligibility mappings, before recovery release."""
from pathlib import Path
import json,hashlib,collections,sys

def sha(p):
    with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def read(p):return json.loads(Path(p).read_text())
def jl(p):return [json.loads(l) for l in Path(p).read_text().splitlines()]
def output(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')

def assemble(case,expected_path,producer_path,audit_path,alias,source,out):
    case=Path(case);out=Path(out);out.mkdir(parents=True,exist_ok=True);expected=jl(expected_path);producer=jl(producer_path);lookup={x['id']:x for x in expected};bindings={x['planned_spec_id']:x for x in producer};assert len(lookup)==len(bindings)==11700 and set(lookup)==set(bindings);records=[];heads=[];paths=[];auditrecords=[];initial=0;actual=0;audinitial=0;audactual=0;seen=set();pmax=0.;mmax=0.;apmax=0.;acvmax=0.;valid=0;numeric=0;intervals=0;wall=0.;cpu=0.;rss=0
    for p in sorted((case/'verification').glob('*/*/seed*/VERIFICATION.json')):
        r=read(p);ident=r['identity'];assert ident['alias']==alias and ident['source_identity_sha256']==source and r['status']=='PASS_NUMERICAL_CHECKS_PENDING_AUDIT_RECOVERY_RELEASE';completion=p.parent/'COMPLETE.json';assert completion.is_file();ids=r['producer_key_ids'];assert len(ids)==len(set(ids))==30 and not seen&set(ids);seen.update(ids);initial+=r['head']['initial_optimizer_calls'];actual+=r['head']['actual_optimizer_calls'];heads.append({'alias':alias,'task':ident['task'],'representation':ident['representation'],'cv_seed':ident['cv_seed'],**r['head']});paths+=r['paths'];wall+=r['wall_seconds'];cpu+=r['CPU_process_seconds'];rss=max(rss,r['peak_RSS_bytes'])
        for x in r['paths']:
            assert x['status']=='PASS';pmax=max(pmax,x['probability_check']['max_abs_residual']);mmax=max(mmax,x['max_metric_draw_CI_abs_residual'])
            for m in x['metric_records']:valid+=m['valid'];numeric+=m['estimate'] is not None;intervals+=m['interval'] is not None
        for uid in ids:
            e=lookup[uid];b=bindings[uid];assert b['status']=='COMPLETE_UNVERIFIED';records.append({'planned_spec_id':uid,'kind':e['k'],'alias':alias,'task':e['t'],'representation':e.get('r'),'cv_seed':e.get('s'),'policy':e.get('p'),'split':e.get('split'),'producer_identity_sha256':b['actual_identity_sha256'],'producer_artifact_sha256':b['artifact_sha256'],'producer_archive_member':b['archive_member'],'producer_selector':b['selector'],'verifier_receipt_member':'candidate/'+str(completion.relative_to(case)),'verifier_receipt_sha256':sha(completion),'verifier_source_identity_sha256':source,'check_status':'PASS_CHECKS_PENDING_PRIVATE_RECOVERY','release_status':'NOT_YET_RELEASED','audit_dependency_scope':alias+' original frozen audit panel','is_fresh_refit':False})
    assert len(heads)==390 and len(paths)==780 and seen==set(lookup) and initial==6240
    audits=[x for x in read(audit_path) if x['k']=='audit_refit' and x['c']==alias];auditkeys=[x for x in read(audit_path) if x['c']==alias];aseen=set()
    for u in audits:
        k='final_norm' if u['r']=='decoder.final_norm' else 'decoder_layer_'+u['r'].rsplit('.',1)[1];root=case/'audits'/u['t']/k/('seed'+str(u['s']));r=read(root/'AUDIT.json');assert r['status']=='PASS' and r['identity']['planned_spec_id']==u['id'] and r['identity']['source_identity_sha256']==source;calls=read(root/'CV_INDEX.json')['calls'];assert len(calls)==16;audinitial+=16;audactual+=r['actual_optimizer_calls'];wall+=r['wall_seconds'];cpu+=r['CPU_process_seconds'];rss=max(rss,r['peak_RSS_bytes'])
        apmax=max(apmax,max(x['max_abs_residual'] for x in r['checks'] if x['atol']==1e-10));acvmax=max(acvmax,max(x['max_abs_residual'] for x in r['checks'] if x['atol']==1e-12));auditrecords.append({'alias':alias,'task':u['t'],'representation':u['r'],'cv_seed':u['s'],'planned_spec_id':u['id'],'audit_receipt_sha256':sha(root/'COMPLETE.json'),'audit_member':'candidate/'+str((root/'COMPLETE.json').relative_to(case)),'selected_C':r['selected_C'],'initial_optimizer_calls':16,'actual_optimizer_calls':r['actual_optimizer_calls'],'retries':r['retries'],'checks':r['checks'],'parameter_content_exactly_equal':r['parameter_content_exactly_equal']})
        for row in [{'planned_spec_id':u['id'],'relative_root':None}]+calls:
            uid=row['planned_spec_id'];assert uid not in aseen;aseen.add(uid);member=root/'COMPLETE.json' if row['relative_root'] is None else root/row['relative_root']/'COMPLETE.json';records.append({'planned_spec_id':uid,'kind':'audit_refit' if row['relative_root'] is None else 'audit_optimizer_call','alias':alias,'task':u['t'],'representation':u['r'],'cv_seed':u['s'],'policy':'independent_refit','split':None,'producer_identity_sha256':read(member)['identity_sha256'],'producer_artifact_sha256':sha(member),'producer_archive_member':'candidate/'+str(member.relative_to(case)),'producer_selector':None,'verifier_receipt_member':'candidate/'+str((root/'COMPLETE.json').relative_to(case)),'verifier_receipt_sha256':sha(root/'COMPLETE.json'),'verifier_source_identity_sha256':source,'check_status':'PASS_CHECKS_PENDING_PRIVATE_RECOVERY','release_status':'NOT_YET_RELEASED','audit_dependency_scope':u['id'],'is_fresh_refit':True})
    assert aseen=={x['id'] for x in auditkeys};records.sort(key=lambda x:x['planned_spec_id']);(out/'ELIGIBLE_INDEX.jsonl').write_text(''.join(json.dumps(x,sort_keys=True,separators=(',',':'),allow_nan=False)+'\n' for x in records));coverage={'schema_version':'s08-case-eligible-coverage-v1','status':'PASS_CHECKS_PENDING_PRIVATE_RECOVERY','alias':alias,'verifier_source_identity_sha256':source,'producer_evidence_keys':11700,'new_audit_keys':len(aseen),'exact_evidence_keys':len(records),'heads':390,'fixed_applications':390,'prediction_paths':780,'metric_vectors':3900,'numeric_metrics':numeric,'intervals_available':intervals,'bootstrap_attempted_values':7800000,'bootstrap_valid_values':valid,'bootstrap_invalid_values':7800000-valid,'producer_initial_calls':initial,'producer_actual_calls':actual,'producer_retries':actual-initial,'fresh_audit_refits':len(audits),'audit_initial_calls':audinitial,'audit_actual_calls':audactual,'audit_retries':audactual-audinitial,'max_probability_abs_residual':pmax,'max_metric_draw_CI_abs_residual':mmax,'max_audit_probability_abs_residual':apmax,'max_audit_CV_abs_residual':acvmax,'aggregate_CPU_process_seconds':cpu,'sum_unit_wall_seconds_not_elapsed_time':wall,'peak_worker_RSS_bytes':rss,'release_status':'NOT_YET_RELEASED'};output(out/'COVERAGE.json',coverage);output(out/'HEAD_PROVENANCE.json',{'records':heads});output(out/'AUDIT_INDEX.json',{'records':auditrecords});return coverage

if __name__=='__main__':print(json.dumps(assemble(*sys.argv[1:]),separators=(',',':')))
